mapper.delete:
delete from STL_SEC_RECON where SEQ_NO  in(
    select SEQ_NO from STL_SEC_RECON_DEAL where TRADE_DATE = to_date(#{execDate,jdbcType=VARCHAR},'yyyyMMdd')

)

delete from STL_SEC_RECON_DETAIL where SEQ_NO  in(
    select SEQ_NO from STL_SEC_RECON_DEAL where TRADE_DATE = to_date(#{execDate,jdbcType=VARCHAR},'yyyyMMdd')

)

mapper.select:
SELECT FINPROD_ID, ENTRUST_TRADE_ID FROM STL_SEC_RECON WHERE (CHECK_RESULT = '1' OR CHECK_RESULT = '3')
AND SETTLE_DATE = TO_DATE(#{execDate,jdbcType=VARCHAR},'yyyyMMdd')
and ENTRUST_TRADE_ID in
#{item.tradeId}
and ENTRUST_TRADE_ID in
#{item.instructionId}

mapper.sql:
SELECT TO_DATE(T1.JYRQ, 'yyyyMMdd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZLB in ('RMB', '人民币') THEN 'CNY' WHEN T1.BZLB in ('HKD', '港币') THEN 'HKD' WHEN T1.BZLB in ('USD', '美元') THEN 'USD' END CCY, CASE WHEN JYLB = '1' THEN '03' WHEN JYLB = '上海' THEN '03' WHEN JYLB = '2' THEN '04' WHEN JYLB = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CASE WHEN T1.GZZLX !=0 THEN CJJG ELSE NULL END PRICE, YJLX UNIT, CASE WHEN T1.GZZLX !=0 THEN null ELSE CJJG END FULL_PRICE, GZZLX INT_AMT, CJJE TRADE_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, CASE WHEN YWBS = '4023' THEN 'T49' WHEN YWBS != '4023' AND CJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN T3.FINPROD_TYPE2 IS NOT NULL THEN T3.FINPROD_TYPE2 ELSE FPT.TYPE_8 END FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO AND T5.TRD_ACCT_CCY = T2.CCY INNER JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID AND ( (T5.TRADE_PLACE = '03' and msd.SH_SEATNO = T1.XWBH) OR (T5.TRADE_PLACE = '04' and msd.SZ_SEATNO = T1.XWBH) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWBH
EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL AND ZYBS IS NULL AND T1.YWBS NOT IN ( '4429', '4431', '4030', '4461', '4448', '4462', '4447', '4446', '债券质押初始交易', '债券质押到期续做新开', '债券质押到期续做了结', '债券质押到期续作（前期合约了结）购回利息', '债券质押提前终止', '债券质押提前终止购回利息', '债券质押购回交易', '债券质押购回利息' ) )
and T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.CJBH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}
UNION ALL SELECT TO_DATE(T1.JYRQ, 'yyyyMMdd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, LSH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZ in ('0', '人民币') THEN 'CNY' WHEN T1.BZ in ('1', '港币') THEN 'HKD' WHEN T1.BZ in ('2', '美元') THEN 'USD' END CCY, CASE WHEN JYSC = '1' THEN '03' WHEN JYSC = '上海' THEN '03' WHEN JYSC = '0' THEN '04' WHEN JYSC = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWDM SEAT_NUMBER, JSFS SETTLEMEN_TYPE, CASE WHEN SJSF > 0 THEN abs(CJSL) * -1 ELSE abs(CJSL) END AS TRADE_NUM, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, YJLXZE INT_AMT, CASE WHEN SJSF > 0 THEN abs(QJCJJE) ELSE abs(QJCJJE) * -1 END AS TRADE_AMT, FYHJ TOTAL_TEEAMT, TO_DATE(HGDQR, 'yyyyMMdd') HGDQR, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, QTF OTHER_FEEAMT, JYJ COMMISSION_AMT, CASE WHEN ZYDM = '220142' THEN 'T49' WHEN ZYDM != '220142' AND QJCJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN T3.FINPROD_TYPE2 IS NOT NULL THEN T3.FINPROD_TYPE2 ELSE FPT.TYPE_8 END FINPROD_TYPE FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY = T2.CCY INNER JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID AND ( (T1.JYSC IN ('1', '上海') AND msd.SH_SEATNO = T1.XWDM) OR (T1.JYSC IN ('0', '深圳') AND msd.SZ_SEATNO = T1.XWDM) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM || '.' || DECODE(T1.JYSC, '0', 'SZ', '深圳', 'SZ', '1', 'SH', '上海', 'SH') LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0', '1', '深圳', '上海') AND EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = to_char(T1.ZYDM) AND ZYBS IS NOT NULL AND to_char(T1.ZYDM) NOT IN( '220131', '220132', '220144', '220143', '220148', '220147', '220134', '220133', '债券回购初始融入', '债券回购初始融出', '债券回购提前收取', '债券回购提前返回', '债券回购续做收取', '债券回购续做返回', '债券回购购回收取', '债券回购购回返回' ) )
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.LSH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}

SELECT TO_DATE(T1.JYRQ, 'yyyyMMdd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZLB in ('RMB', '人民币') THEN 'CNY' WHEN T1.BZLB in ('HKD', '港币') THEN 'HKD' WHEN T1.BZLB in ('USD', '美元') THEN 'USD' END CCY, CASE WHEN JYLB = '1' THEN '03' WHEN JYLB = '上海' THEN '03' WHEN JYLB = '2' THEN '04' WHEN JYLB = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CASE WHEN T1.GZZLX !=0 THEN CJJG ELSE NULL END PRICE, YJLX UNIT, CASE WHEN T1.GZZLX !=0 THEN null ELSE CJJG END FULL_PRICE, GZZLX INT_AMT, CJJE TRADE_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, CASE WHEN YWBS = '4023' THEN 'T49' WHEN YWBS != '4023' AND CJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN T3.FINPROD_TYPE2 IS NOT NULL THEN T3.FINPROD_TYPE2 ELSE FPT.TYPE_8 END FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO AND T5.TRD_ACCT_CCY = T2.CCY INNER JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID AND ( (T5.TRADE_PLACE = '03' and msd.SH_SEATNO = T1.XWBH) OR (T5.TRADE_PLACE = '04' and msd.SZ_SEATNO = T1.XWBH) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWBH
EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL AND ZYBS IS NULL AND T1.YWBS NOT IN ( '4429', '4431', '4030', '4461', '4448', '4462', '4447', '4446', '债券质押初始交易', '债券质押到期续做新开', '债券质押到期续做了结', '债券质押到期续作（前期合约了结）购回利息', '债券质押提前终止', '债券质押提前终止购回利息', '债券质押购回交易', '债券质押购回利息' ) ) AND NOT EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL AND T1.YWBS = '4023' AND T1.CJSL < 0 )
and T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.CJBH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}
UNION ALL SELECT TO_DATE(T1.JYRQ, 'yyyyMMdd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, LSH TRADE_ID, WTBH INSTRUCTION_ID, CASE WHEN T1.BZ in ('0', '人民币') THEN 'CNY' WHEN T1.BZ in ('1', '港币') THEN 'HKD' WHEN T1.BZ in ('2', '美元') THEN 'USD' END CCY, CASE WHEN JYSC = '1' THEN '03' WHEN JYSC = '上海' THEN '03' WHEN JYSC = '0' THEN '04' WHEN JYSC = '深圳' THEN '04' END TRADE_MARKET , T5.SEC_ACCT_ID SEC_ACCT_ID, XWDM SEAT_NUMBER, JSFS SETTLEMEN_TYPE, CASE WHEN SJSF > 0 THEN abs(CJSL) * -1 ELSE abs(CJSL) END AS TRADE_NUM, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, YJLXZE INT_AMT, CASE WHEN SJSF > 0 THEN abs(QJCJJE) ELSE abs(QJCJJE) * -1 END AS TRADE_AMT, FYHJ TOTAL_TEEAMT, TO_DATE(HGDQR, 'yyyyMMdd') HGDQR, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, QTF OTHER_FEEAMT, JYJ COMMISSION_AMT, CASE WHEN ZYDM = '220142' THEN 'T49' WHEN ZYDM != '220142' AND QJCJJE >0 THEN 'T02' ELSE 'T01' END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN T3.FINPROD_TYPE2 IS NOT NULL THEN T3.FINPROD_TYPE2 ELSE FPT.TYPE_8 END FINPROD_TYPE FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5.BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY = T2.CCY INNER JOIN MST_SALE_DEPARTMENT msd ON T2.OWN_DEPT = msd.SALE_DEPID AND ( (T1.JYSC IN ('1', '上海') AND msd.SH_SEATNO = T1.XWDM) OR (T1.JYSC IN ('0', '深圳') AND msd.SZ_SEATNO = T1.XWDM) ) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM || '.' || DECODE(T1.JYSC, '0', 'SZ', '深圳', 'SZ', '1', 'SH', '上海', 'SH') LEFT JOIN FIN_PRODUCT_TYPE FPT ON T3.FINPROD_ID = FPT.FINPROD_ID LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0', '1', '深圳', '上海') AND EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = to_char(T1.ZYDM) AND ZYBS IS NOT NULL AND to_char(T1.ZYDM) NOT IN( '220131', '220132', '220144', '220143', '220148', '220147', '220134', '220133', '债券回购初始融入', '债券回购初始融出', '债券回购提前收取', '债券回购提前返回', '债券回购续做收取', '债券回购续做返回', '债券回购购回收取', '债券回购购回返回' ) ) AND NOT EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = to_char(T1.ZYDM) AND ZYBS IS NOT NULL AND to_char(T1.ZYDM) = '220142' AND T1.CJSL < 0 )
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T3.FINPROD_ID not in
#{item.finprodId}
and T1.WTBH not in
#{item.entrustTradeId}
and T1.LSH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}

mapper.select:
SELECT CUSTOMER_ID, ENTRUST_ID INSTRUCTION_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, SEC_ACCT_ID, MARKET_ID, FINPROD_ID, FINPROD_TYPE, 'H01' REPO_TYPE, SUM(TRADE_NUM) TRADE_NUM, SUM(TRADE_AMT) TRADE_AMT, SUM(INT_AMT) INT_AMT, SUM(HAPPEN_AMT) HAPPEN_AMT, SUM(HGDQJE) HGDQJE, SUM(STAMP_FEE) STAMP_FEE, SUM(JSF_AMT) JSF_AMT , SUM(GHF_AMT) GHF_AMT, SUM(ZGF_AMT) ZGF_AMT, SUM(SETTLE_FEE) SETTLE_FEE, SUM(TRADE_FEE) TRADE_FEE, SUM(COMMISSION_AMT) COMMISSION_AMT, SUM(OTHER_FEEAMT) OTHER_FEEAMT, SUM(TOTAL_TEEAMT) TOTAL_TEEAMT FROM ( SELECT TO_DATE(T1.JYRQ,'yyyyMMdd') TRADE_DATE, a.BROKER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH ENTRUNST_ID, CASE WHEN T1.BZLB = 'RMB' THEN 'CNY' WHEN T1.BZLB = '人民币' THEN 'CNY' WHEN T1.BZLB = 'HKD' THEN 'HKD' WHEN T1.BZLB = '港币' THEN 'HKD' WHEN T1.BZLB = 'USD' THEN 'USD' WHEN T1.BZLB = '美元' THEN 'HKD' END CCY, T5.TRADE_PLACE TRADE_MARKET, T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CASE WHEN YWBS = '4446' AND JYLB = '2' THEN 0 WHEN YWBS = '债券质押到期续做了结' AND JYLB = '深圳' THEN 0 ELSE CJSL END TRADE_NUM, CJJG PRICE, NULL UNIT, NULL FULL_PRICE, NULL INT_AMT, CASE WHEN FSJE < 0 THEN abs(CJJE)*-1 ELSE abs(CJJE) END TRADE_AMT, FSJE HAPPEN_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, WTBH ENTRUST_ID, CASE WHEN YWBS = '4429' and MMFX= '1' then '04' WHEN YWBS = '债券质押初始交易' and MMFX= '买' then '04' WHEN YWBS = '4429' and MMFX= '2' then '03' WHEN YWBS = '债券质押初始交易' and MMFX= '卖' then '03' WHEN YWBS = '4430' and MMFX= '1' then 'T95' WHEN YWBS = '债券质押购回交易' and MMFX= '买' then 'T95' WHEN YWBS = '4430' and MMFX= '2' then 'T95' WHEN YWBS = '债券质押购回交易' and MMFX= '卖' then 'T95' WHEN YWBS = '4431' and MMFX= '1' then 'T95' WHEN YWBS = '债券质押购回利息' and MMFX= '买' then 'T95' WHEN YWBS = '4431' and MMFX= '2' then 'T95' WHEN YWBS = '债券质押购回利息' and MMFX= '卖' then 'T95' WHEN YWBS = '4461' and MMFX= '1' then 'T54' WHEN YWBS = '债券质押提前终止购回利息' and MMFX= '买' then 'T54' WHEN YWBS = '4461' and MMFX= '2' then 'T54' WHEN YWBS = '债券质押提前终止购回利息' and MMFX= '卖' then 'T54' WHEN YWBS = '4448' and MMFX= '1' then 'T54' WHEN YWBS = '债券质押提前终止' and MMFX= '买' then 'T54' WHEN YWBS = '4448' and MMFX= '2' then 'T54' WHEN YWBS = '债券质押提前终止' and MMFX= '卖' then 'T54' WHEN YWBS = '4462' and MMFX= '1' then 'T56' WHEN YWBS = '债券质押到期续作（前期合约了结）购回利息' and MMFX= '买' then 'T56' WHEN YWBS = '4462' and MMFX= '2' then 'T56' WHEN YWBS = '债券质押到期续作（前期合约了结）购回利息' and MMFX= '卖' then 'T56' WHEN YWBS = '4447' and MMFX= '1' then 'T56' WHEN YWBS = '债券质押到期续做了结' and MMFX= '买' then 'T56' WHEN YWBS = '4447' and MMFX= '2' then 'T56' WHEN YWBS = '债券质押到期续做了结' and MMFX= '卖' then 'T56' WHEN YWBS = '4446' and MMFX='1' then 'T56' WHEN YWBS = '债券质押到期续做新开' and MMFX='买' then 'T56' WHEN YWBS = '4446' and MMFX= '2' then 'T56' WHEN YWBS = '债券质押到期续做新开' and MMFX='卖' then 'T56' ELSE NULL END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN YWBS = '4429' and MMFX= '1' then 'F03' WHEN YWBS = '债券质押初始交易' and MMFX= '买' then 'F03' WHEN YWBS = '4429' and MMFX= '2' then 'F02' WHEN YWBS = '债券质押初始交易' and MMFX= '卖' then 'F02' WHEN YWBS = '4430' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押购回交易' and MMFX= '买' then 'F02' WHEN YWBS = '4430' and MMFX= '2' then 'F03' WHEN YWBS = '债券质押购回交易' and MMFX= '卖' then 'F03' WHEN YWBS = '4431' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押购回利息' and MMFX= '买' then 'F02' WHEN YWBS = '4431' and MMFX= '2' then 'F03' WHEN YWBS = '债券质押购回利息' and MMFX= '卖' then 'F03' WHEN YWBS = '4461' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押提前终止购回利息' and MMFX= '买' then 'F02' WHEN YWBS = '4461' and MMFX= '2' then 'F03' WHEN YWBS = '债券质押提前终止购回利息' and MMFX= '卖' then 'F03' WHEN YWBS = '4448' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押提前终止' and MMFX= '买' then 'F02' WHEN YWBS = '4448' and MMFX= '2' then 'F03' WHEN YWBS = '债券质押提前终止' and MMFX= '卖' then 'F03' WHEN YWBS = '4462' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押到期续作（前期合约了结）购回利息' and MMFX= '买' then 'F02' WHEN YWBS = '4462' and MMFX= '2' then 'F02' WHEN YWBS = '债券质押到期续作（前期合约了结）购回利息' and MMFX= '卖' then 'F02' WHEN YWBS = '4447' and MMFX= '1' then 'F02' WHEN YWBS = '债券质押到期续做了结' and MMFX= '买' then 'F02' WHEN YWBS = '4447' and MMFX= '2' then 'F02' WHEN YWBS = '债券质押到期续做了结' and MMFX= '卖' then 'F02' WHEN YWBS = '4446' and MMFX='1' then 'F02' WHEN YWBS = '债券质押到期续做新开' and MMFX='买' then 'F02' WHEN YWBS = '4446' and MMFX= '2' then 'F02' WHEN YWBS = '债券质押到期续做新开' and MMFX='卖' then 'F02' ELSE NULL END FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5. BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO AND T5.TRD_ACCT_CCY= T2.CCY INNER JOIN MST_SALE_DEPARTMENT a ON T2.OWN_DEPT = a.SALE_DEPID AND ((T5.TRADE_PLACE = '03' and a.SH_SEATNO = T1.XWBH) OR (T5.TRADE_PLACE = '04' and a.SZ_SEATNO = T1.XWBH)) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) WHERE EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL AND YWBS IN ( '4429', '4431', '4030', '4461', '4448', '4462', '4447', '4446', '债券质押初始交易', '债券质押到期续做新开', '债券质押到期续做了结', '债券质押到期续作（前期合约了结）购回利息', '债券质押提前终止', '债券质押提前终止购回利息', '债券质押购回交易', '债券质押购回利息') )
AND a.BROKER_ID IN
#{item.customerId}
and T1.WTBH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}
) tx GROUP BY CUSTOMER_ID, ENTRUST_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, MARKET_ID, FINPROD_ID, FINPROD_TYPE, SEC_ACCT_ID
UNION ALL
SELECT CUSTOMER_ID, INSTRUCTION_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, SEC_ACCT_ID, MARKET_ID, FINPROD_ID, FINPROD_TYPE, 'H01' REPO_TYPE, SUM(TRADE_NUM) TRADE_NUM, SUM(TRADE_AMT) TRADE_AMT, SUM(INT_AMT) INT_AMT, SUM(HAPPEN_AMT) HAPPEN_AMT, SUM(HGDQJE) HGDQJE, SUM(STAMP_FEE) STAMP_FEE, SUM(JSF_AMT) JSF_AMT , SUM(GHF_AMT) GHF_AMT, SUM(ZGF_AMT) ZGF_AMT, SUM(SETTLE_FEE) SETTLE_FEE, SUM(TRADE_FEE) TRADE_FEE, SUM(COMMISSION_AMT) COMMISSION_AMT, SUM(OTHER_FEEAMT) OTHER_FEEAMT, SUM(TOTAL_TEEAMT) TOTAL_TEEAMT FROM ( SELECT T4.CUSTOMER_ID, WTBH INSTRUCTION_ID, T2.ACCT_NO ACCOUT, XWDM SEAT_NUMBER, TO_DATE(T1.JYRQ,'yyyyMMdd') TRADE_DATE, CASE WHEN T1.BZ = '0' THEN 'CNY' WHEN T1.BZ = '人民币' THEN 'CNY' WHEN T1.BZ = '1' THEN 'HKD' WHEN T1.BZ = '港币' THEN 'HKD' WHEN T1.BZ = '2' THEN 'USD' WHEN T1.BZ = '美元' THEN 'USD' END CCY, T5.TRADE_PLACE TRADE_MARKET, CASE WHEN to_char(ZYDM) = '220131' then '03' WHEN to_char(ZYDM) = '债券回购初始融入' then '03' WHEN to_char(ZYDM) = '220132 ' then '04' WHEN to_char(ZYDM) = '债券回购初始融出 ' then '04' WHEN to_char(ZYDM) = '220143' then 'T54' WHEN to_char(ZYDM) = '债券回购提前返回' then 'T54' WHEN to_char(ZYDM) = '220144' then 'T54' WHEN to_char(ZYDM) = '债券回购提前收取' then 'T54' WHEN to_char(ZYDM) = '220147' then 'T95' WHEN to_char(ZYDM) = '债券回购续做返回' then 'T95' WHEN to_char(ZYDM) = '220148' then 'T95' WHEN to_char(ZYDM) = '债券回购续做收取' then 'T95' WHEN to_char(ZYDM) = '220133' then 'T07' WHEN to_char(ZYDM) = '债券回购购回返回' then 'T07' WHEN to_char(ZYDM) = '220134' then 'T07' WHEN to_char(ZYDM) = '债券回购购回收取' then 'T07' ELSE NULL END PS, LSH TRADE_ID, T5.SEC_ACCT_ID SEC_ACCT_ID, JSFS SETTLEMEN_TYPE, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, CASE WHEN HGDQR IS NOT NULL THEN TO_DATE(HGDQR, 'yyyyMMdd') ELSE NULL END HGDQR, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN to_char(ZYDM) = '220131' then 'F02' WHEN to_char(ZYDM) = '债券回购初始融入' then 'F02' WHEN to_char(ZYDM) = '220132' then 'F03' WHEN to_char(ZYDM) = '债券回购初始融出' then 'F03' WHEN to_char(ZYDM) = '220143' then 'F02' WHEN to_char(ZYDM) = '债券回购提前返回' then 'F02' WHEN to_char(ZYDM) = '220144 ' then 'F03' WHEN to_char(ZYDM) = '债券回购提前收取 ' then 'F03' WHEN to_char(ZYDM) = '220147' then 'F02' WHEN to_char(ZYDM) = '债券回购续做返回' then 'F02' WHEN to_char(ZYDM) = '220148' then 'F03' WHEN to_char(ZYDM) = '债券回购续做收取' then 'F03' WHEN to_char(ZYDM) = '220133' then 'F02' WHEN to_char(ZYDM) = '债券回购购回返回' then 'F02' WHEN to_char(ZYDM) = '220134' then 'F03' WHEN to_char(ZYDM) = '债券回购购回收取' then 'F03' ELSE NULL END FINPROD_TYPE, CJSL TRADE_NUM, QJCJJE TRADE_AMT, YJLXZE INT_AMT, SJSF HAPPEN_AMT, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, JYJ COMMISSION_AMT, QTF OTHER_FEEAMT, FYHJ TOTAL_TEEAMT FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5. BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO AND T5.TRD_ACCT_CCY= T2.CCY INNER JOIN MST_SALE_DEPARTMENT a ON T2.OWN_DEPT = a.SALE_DEPID AND ((T5.TRADE_PLACE = '03' and a.SH_SEATNO = T1.XWDM) OR (T5.TRADE_PLACE = '04' and a.SZ_SEATNO = T1.XWDM)) LEFT JOIN STL_CAPACCT_INFO T7 ON T7.BUSI_ACCT_NO = T1.ZJZH LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0','1','上海','深圳') AND EXISTS ( SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = T1.ZYDM AND T1.ZYDM IS NOT NULL AND to_char(T1.ZYDM) IN ( '220131', '220132', '220144', '220143', '220148', '220147', '220134', '220133', '债券回购初始融入', '债券回购初始融出', '债券回购提前返回', '债券回购提前收取', '债券回购续做返回', '债券回购续做收取', '债券回购购回返回', '债券回购购回收取') )
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T1.WTBH not in
#{item.entrustTradeId}
AND T1.JYRQ = #{execDate,jdbcType=VARCHAR}
)temp GROUP BY CUSTOMER_ID, INSTRUCTION_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, MARKET_ID, FINPROD_ID, FINPROD_TYPE, SEC_ACCT_ID

SELECT CUSTOMER_ID, ENTRUST_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, SUM(TRADE_NUM) TRADE_NUM, SUM(TRADE_AMT), SUM(INT_AMT) INT_AMT, SUM(HAPPEN_AMT) HAPPEN_AMT, SUM(HGDQJE) HGDQJE, SUM(STAMP_FEE) STAMP_FEE, SUM(JSF_AMT) JSF_AMT , SUM(GHF_AMT) GHF_AMT, SUM(ZGF_AMT) ZGF_AMT, SUM(SETTLE_FEE) SETTLE_FEE, SUM(TRADE_FEE) TRADE_FEE, SUM(COMMISSION_AMT) COMMISSION_AMT, SUM(OTHER_FEEAMT), SUM(TOTAL_TEEAMT) FROM ( SELECT TO_DATE(T1.JYRQ, 'yyyy-MM-dd') TRADE_DATE, a.BROKER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH ENTRUNST_ID, CASE WHEN T1.BZLB = 'RMB' THEN 'CNY' WHEN T1.BZLB = 'HKD' THEN 'HKD' WHEN T1.BZLB = 'USD' THEN 'USD' END CCY, T5.TRADE_PLACE TRADE_MARKET, T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CJJG PRICE, NULL UNIT, NULL FULL_PRICE, NULL INT_AMT, case when CJJE<0 then CJJE*-1 else CJJE end TRADE_AMT , CJJE HAPPEN_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, WTBH ENTRUST_ID, CASE WHEN YWBS = '4429' and MMFX= '2' then '03' WHEN YWBS = '4429' and MMFX= '1' then '03' WHEN YWBS = '4030' and MMFX= '1' then 'T95' WHEN YWBS = '4030' and MMFX= '2' then 'T95' WHEN YWBS = '4031' and MMFX= '2' then 'T95' WHEN YWBS = '4446' and MMFX= '1' then 'T95' WHEN YWBS = '4446' and MMFX= '2' then 'T95' WHEN YWBS = '4447' and MMFX= '1' then 'T95' WHEN YWBS = '4447' and MMFX= '2' then 'T95' ELSE NULL END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN YWBS = '4429' and MMFX= '2' then 'F02' WHEN YWBS = '4429' and MMFX= '1' then 'F03' WHEN YWBS = '4030' and MMFX= '1' then 'F02' WHEN YWBS = '4030' and MMFX= '2' then 'F03' WHEN YWBS = '4031' and MMFX= '2' then 'F03' WHEN YWBS = '4446' and MMFX= '1' then 'F02' WHEN YWBS = '4446' and MMFX= '2' then 'F02' WHEN YWBS = '4447' and MMFX= '2' then 'F02' WHEN YWBS = '4447' and MMFX= '1' then 'F02' ELSE NULL END FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5. BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY= T2.CCY LEFT JOIN MST_SALE_DEPARTMENT a ON T2.OWN_DEPT = a.SALE_DEPID AND ((T5.TRADE_PLACE = '03' and a.SH_SEATNO = T1.XWBH) OR (T5.TRADE_PLACE = '04' and a.SZ_SEATNO = T1.XWBH)) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) where T5.TRADE_PLACE = '04' AND EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL and ZYBS IN ('4429','4431','4030','4461','4448','4462','4447','4446'))
AND a.BROKER_ID IN
#{item.customerId}
and T1.WTBH not in
#{item.entrustTradeId}
) GROUP BY CUSTOMER_ID, ENTRUST_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS union all
SELECT CUSTOMER_ID, ENTRUST_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS, SUM(TRADE_NUM) TRADE_NUM, SUM(TRADE_AMT), SUM(INT_AMT) INT_AMT, SUM(HAPPEN_AMT) HAPPEN_AMT, SUM(HGDQJE) HGDQJE, SUM(STAMP_FEE) STAMP_FEE, SUM(JSF_AMT) JSF_AMT , SUM(GHF_AMT) GHF_AMT, SUM(ZGF_AMT) ZGF_AMT, SUM(SETTLE_FEE) SETTLE_FEE, SUM(TRADE_FEE) TRADE_FEE, SUM(COMMISSION_AMT) COMMISSION_AMT, SUM(OTHER_FEEAMT), SUM(TOTAL_TEEAMT) FROM( SELECT TO_DATE(T1.JYRQ, 'yyyy-MM-dd') TRADE_DATE, a.BROKER_ID CUSTOMER_ID, CJBH TRADE_ID, WTBH ENTRUST_ID, CASE WHEN T1.BZLB = 'RMB' THEN 'CNY' WHEN T1.BZLB = 'HKD' THEN 'HKD' WHEN T1.BZLB = 'USD' THEN 'USD' END CCY, T5.TRADE_PLACE TRADE_MARKET, T5.SEC_ACCT_ID SEC_ACCT_ID, XWBH SEAT_NUMBER, '' SETTLEMEN_TYPE, CJSL TRADE_NUM, CJJG PRICE, NULL UNIT, NULL FULL_PRICE, NULL INT_AMT, case when CJJE<0 then CJJE*-1 else CJJE end TRADE_AMT , CJJE HAPPEN_AMT, NULL TOTAL_TEEAMT, NULL HGDQR, NULL HGDQJE, YHS STAMP_FEE, NULL JSF_AMT, GHF GHF_AMT, NULL ZGF_AMT, NULL SETTLE_FEE, NULL TRADE_FEE, NULL OTHER_FEEAMT, YJ COMMISSION_AMT, CASE WHEN YWBS = '4429' and MMFX= '2' then '03' WHEN YWBS = '4429' and MMFX= '1' then '03' WHEN YWBS = '4430' and MMFX= '1' then 'T95' WHEN YWBS = '4430' and MMFX= '2' then 'T95' WHEN YWBS = '4431' and MMFX= '1' then 'T95' WHEN YWBS = '4431' and MMFX= '2' then 'T95' WHEN YWBS = '4461' and MMFX= '1' then 'T54' WHEN YWBS = '4448' and MMFX= '1' then 'T54' WHEN YWBS = '4461' and MMFX= '2' then 'T54' WHEN YWBS = '4448' and MMFX= '2' then 'T54' WHEN YWBS = '4462' and MMFX= '1' then 'T95' WHEN YWBS = '4447' and MMFX= '1' then 'T95' WHEN YWBS = '4446' and MMFX= '2' then 'T95' WHEN YWBS = '4462' and MMFX= '2' then 'T95' WHEN YWBS = '4447' and MMFX= '2' then 'T95' WHEN YWBS = '4446' and MMFX='1' then 'T95' ELSE NULL END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN YWBS = '4429' and MMFX= '2' then 'F02' WHEN YWBS = '4429' and MMFX= '1' then 'F03' WHEN YWBS = '4430' and MMFX= '1' then 'F02' WHEN YWBS = '4430' and MMFX= '2' then 'F03' WHEN YWBS = '4431' and MMFX= '1' then 'F02' WHEN YWBS = '4431' and MMFX= '2' then 'F03' WHEN YWBS = '4461' and MMFX= '1' then 'F02' WHEN YWBS = '4448' and MMFX= '1' then 'F02' WHEN YWBS = '4461' and MMFX= '2' then 'F03' WHEN YWBS = '4448' and MMFX= '2' then 'F03' WHEN YWBS = '4462' and MMFX= '1' then 'F02' WHEN YWBS = '4447' and MMFX= '1' then 'F02' WHEN YWBS = '4446' and MMFX= '2' then 'F02' WHEN YWBS = '4462' and MMFX= '2' then 'F02' WHEN YWBS = '4447' and MMFX= '2' then 'F02' WHEN YWBS = '4446' and MMFX='1' then 'F02' ELSE NULL END FINPROD_TYPE FROM INTERF_DZD T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5. BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY= T2.CCY LEFT JOIN MST_SALE_DEPARTMENT a ON T2.OWN_DEPT = a.SALE_DEPID AND ((T5.TRADE_PLACE = '03' and a.SH_SEATNO = T1.XWBH) OR (T5.TRADE_PLACE = '04' and a.SZ_SEATNO = T1.XWBH)) LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM ||DECODE(T5.TRADE_PLACE,'03','.SH','04','.SZ' ) where T5.TRADE_PLACE = '03' AND EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.JYLB = T1.JYLB AND T6.YWBS = T1.YWBS AND ZYBS IS NULL and T1.YWBS IN ('4429','4431','4030','4461','4448','4462','4447','4446'))
AND a.BROKER_ID IN
#{item.customerId}
and T1.WTBH not in
#{item.entrustTradeId}
) tx GROUP BY CUSTOMER_ID, ENTRUST_ID, ACCOUT, SEAT_NUMBER, TRADE_DATE, CCY, TRADE_MARKET, PS
UNION ALL SELECT TO_DATE(T1.JYRQ, 'yyyy-MM-dd') TRADE_DATE, T4.CUSTOMER_ID CUSTOMER_ID, LSH TRADE_ID, WTBH ENTRUNST_ID, CASE WHEN T1.BZ = '0' THEN 'CNY' WHEN T1.BZ = '1' THEN 'HKD' WHEN T1.BZ = '2' THEN 'USD' END CCY, T5.TRADE_PLACE TRADE_MARKET, T5.SEC_ACCT_ID SEC_ACCT_ID, XWDM SEAT_NUMBER, JSFS SETTLEMEN_TYPE, CJSL TRADE_NUM, CJJJ PRICE, DWYJLX UNIT, CJQJ FULL_PRICE, YJLXZE INT_AMT, QJCJJE TRADE_AMT, SJSF HAPPEN_AMT, FYHJ TOTAL_TEEAMT, HGDQR HGDQR, HGDQJE HGDQJE, YHS STAMP_FEE, JSF JSF_AMT, GHF GHF_AMT, ZGF ZGF_AMT, QSF SETTLE_FEE, JYGF TRADE_FEE, QTF OTHER_FEEAMT, JYJ COMMISSION_AMT, WTBH ENTRUST_ID, CASE WHEN ZYDM = '220131' then '03' WHEN ZYDM = '220132 ' then '04' WHEN ZYDM = '220143' then 'T54' WHEN ZYDM = '220144' then 'T54' WHEN ZYDM = '220147' then 'T95' WHEN ZYDM = '220148' then 'T95' WHEN ZYDM = '220133' then 'T07' WHEN ZYDM = '220134' then 'T07' ELSE NULL END PS, T2.ACCT_NO ACCOUT, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_MARKET_ID END MARKET_ID, CASE WHEN T3.FINPROD_ID IS NULL THEN T1.ZQDM ELSE T3.FINPROD_ID END FINPROD_ID, CASE WHEN ZYDM = '220131' then 'F02' WHEN ZYDM = '220132' then 'F03' WHEN ZYDM = '220143 ' then 'F02' WHEN ZYDM = '220144 ' then 'F03' WHEN ZYDM = '220147' then 'F02' WHEN ZYDM = '220148' then 'F03' WHEN ZYDM = '220133' then 'F02' WHEN ZYDM = '220134' then 'F03' ELSE NULL END FINPROD_TYPE FROM INTERF_ZX_ZJGFLS T1 LEFT JOIN STL_SEC_ACCT_INFO T5 ON T5. BOND_ID = T1.ZQZH LEFT JOIN STL_CAPACCT_INFO T2 ON T5.TRD_ACCT_ID = T2.ACCT_NO and T5.TRD_ACCT_CCY= T2.CCY LEFT JOIN MST_SALE_DEPARTMENT a ON T2.OWN_DEPT = a.SALE_DEPID AND ((T5.TRADE_PLACE = '03' and a.SH_SEATNO = T1.XWDM) OR (T5.TRADE_PLACE = '04' and a.SZ_SEATNO = T1.XWDM)) LEFT JOIN STL_CAPACCT_INFO T7 ON T7.BUSI_ACCT_NO = T1.ZJZH LEFT JOIN FIN_PRODUCT T3 ON T3.FINPROD_MARKET_ID = T1.ZQDM || '.' || DECODE(T1.JYSC, '0', 'SH', '1' , 'SZ') LEFT JOIN MST_SEAT T4 ON T4.SEAT_ID = T1.XWDM WHERE T1.JYSC IN ('0','1') and EXISTS (SELECT 1 FROM STL_SEC_RECON_CONFIG T6 WHERE T6.ZYBS = T1.ZYDM AND T1.ZYDM IS NOT NULL and T1.ZYDM IN ('220131','220132','220144','220143','220148','220147','220134','220133') ) //STL_SEC_RECON_CONFIG表里数据初始化的，配置哪些明细数据需要处理
AND T4.CUSTOMER_ID IN
#{item.customerId}
and T1.WTBH not in
#{item.entrustTradeId}
